CAMPOS_REV = ["unidad_declarada", "espacio_definicion", "espacio_aplicacion", "fuente", "rango_chico", "rango_medio", "rango_grande", "discrepancia", "hallazgo", "revisada_a_mano"]


def main():
    bruto = list(csv.DictReader(open(AQUI / "censo_bruto.csv", encoding="utf-8")))
    usados = set()
    out = []
    for f in bruto:
        key = f["archivo_linea"]
        cur = CURADO.get(key)
        if cur is None and f["contexto"] == "perfil_efectivo":
            # claves 'pipeline/profile.py:?NOMBRE': se casan solo con la fila del perfil efectivo de ese nombre
            k = "pipeline/profile.py:?" + f["nombre"]
            if k in CURADO:
                cur = CURADO[k]
                key = k
        row = dict(f)
        if cur:
            usados.add(key)
            for c in CAMPOS_REV:
                row[c] = cur.get(c, "")
            row["revisada_a_mano"] = "si"
            if cur.get("sensor"):
                row["sensor"] = cur["sensor"]
            if cur.get("nombre"):
                row["nombre_revision"] = cur["nombre"]
        else:
            for c in CAMPOS_REV:
                row[c] = "no revisada"
            row["revisada_a_mano"] = "no"
            row["nombre_revision"] = ""
        out.append(row)
    # filas curadas que no estan en el bruto (constantes agrupadas o sin linea exacta)
    for k, v in CURADO.items():
        if k in usados:
            continue
        row = {c: "" for c in bruto[0].keys()}
        row.update({"archivo_linea": k, "valor": "", "contexto": "curado_sin_fila_bruta", "nombre": v.get("nombre", ""),
                    "sensor": v.get("sensor", ""), "nombre_revision": v.get("nombre", "")})
        for c in CAMPOS_REV:
            row[c] = v.get(c, "")
        row["revisada_a_mano"] = "si (sin fila bruta: constante agrupada o leida del perfil)"
        out.append(row)
    campos = list(bruto[0].keys()) + ["nombre_revision"] + CAMPOS_REV
    with open(AQUI / "censo_magnitudes.csv", "w", newline="", encoding="utf-8") as fh:
        w = csv.DictWriter(fh, fieldnames=campos, extrasaction="ignore")
        w.writeheader()
        w.writerows(out)
    n_rev = sum(1 for r in out if r["revisada_a_mano"].startswith("si"))
    n_disc = sum(1 for r in out if r["discrepancia"].startswith("si"))
    n_sf = sum(1 for r in out if "SIN FUENTE" in (r.get("fuente") or ""))
    print(f"filas: {len(out)}; revisadas a mano: {n_rev}; con discrepancia: {n_disc}; SIN FUENTE: {n_sf}")
    print("curadas sin fila bruta:", [k for k in CURADO if k not in usados])


if __name__ == "__main__":
    main()
